package com.example.digitalnotam.scenario.rwycls;

import com.example.digitalnotam.baseline.*;import com.example.digitalnotam.domain.Notam;import com.example.digitalnotam.xml.CommonDigitalNotamBuilder;import org.w3c.dom.*;import java.util.*;

final class RwyClsScenarioValidator {
    void validate(Document d,Notam n,BaselineRunwayCatalog.ResolvedTarget target){NodeList events=d.getElementsByTagNameNS(CommonDigitalNotamBuilder.EVENT,"Event");if(events.getLength()!=1)throw new IllegalArgumentException("RWY.CLS 必须恰好包含一个 Event");Element ets=CommonDigitalNotamBuilder.one(d,CommonDigitalNotamBuilder.EVENT,"EventTimeSlice");expected(ets,"scenario","RWY.CLS");expected(ets,"version","2.0");NodeList features=d.getElementsByTagNameNS(CommonDigitalNotamBuilder.AIXM,"RunwayDirection");if(features.getLength()!=target.directions().size())throw new IllegalArgumentException("RunwayDirection TEMPDELTA 数量不正确");String eventUuid=((Element)events.item(0)).getAttributeNS(CommonDigitalNotamBuilder.GML,"id").replaceFirst("^uuid\\.","");Set<String> expected=target.directions().stream().map(BaselineRunwayCatalog.RunwayDirectionBaseline::uuid).collect(java.util.stream.Collectors.toSet()),actual=new HashSet<>(),ids=new HashSet<>();for(int i=0;i<features.getLength();i++){Element feature=(Element)features.item(i);actual.add(feature.getAttributeNS(CommonDigitalNotamBuilder.GML,"id").replaceFirst("^uuid\\.",""));Element slice=BaselineAirportHeliportCatalog.first(feature,"RunwayDirectionTimeSlice");expected(slice,"interpretation","TEMPDELTA");int normal=0,closed=0;for(Element w:BaselineAirportHeliportCatalog.directChildren(slice,"availability")){String status=BaselineAirportHeliportCatalog.text(w,"operationalStatus");if("NORMAL".equals(status))normal++;if("CLOSED".equals(status))closed++;}if(normal==0||closed!=1)throw new IllegalArgumentException("每个 RunwayDirection TEMPDELTA 必须包含基线 NORMAL 和一个 CLOSED availability");Element link=BaselineAirportHeliportCatalog.first(feature,"theEvent");if(link==null||!("urn:uuid:"+eventUuid).equals(link.getAttributeNS(CommonDigitalNotamBuilder.XLINK,"href")))throw new IllegalArgumentException("RunwayDirection theEvent 未指向当前 Event");}if(!actual.equals(expected))throw new IllegalArgumentException("RWY.CLS 受影响方向与输入不一致");NodeList all=d.getElementsByTagNameNS("*","*");for(int i=0;i<all.getLength();i++){Element e=(Element)all.item(i);if(e.hasAttributeNS(CommonDigitalNotamBuilder.GML,"id")&&!ids.add(e.getAttributeNS(CommonDigitalNotamBuilder.GML,"id")))throw new IllegalArgumentException("重复 gml:id");}}
    private static void expected(Element e,String local,String value){if(!value.equals(BaselineAirportHeliportCatalog.text(e,local)))throw new IllegalArgumentException(local+" 必须为 "+value);}
}
